import{G as e,W as t,n,rt as r}from"./chunks/framework.CHX_0itn.js";var i=JSON.parse(`{"title":"关于项目","description":"","frontmatter":{"title":"关于项目"},"headers":[],"relativePath":"introduce/about.md","filePath":"introduce/about.md"}`),a={name:`introduce/about.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="❓-关于本项目" tabindex="-1">❓ 关于本项目 <a class="header-anchor" href="#❓-关于本项目" aria-label="Permalink to “❓ 关于本项目”">​</a></h1><p>这是一份面向学生与网络爱好者的开源技术文档，旨在深入浅出地讲解校园网多设备检测（NAT 共享限制）的原理，并提供系统化的应对方案与配置教程。</p><h2 id="💡-项目初衷" tabindex="-1">💡 项目初衷 <a class="header-anchor" href="#💡-项目初衷" aria-label="Permalink to “💡 项目初衷”">​</a></h2><p>在许多校园网环境中，运营商或学校网络中心常通过各种技术手段限制单账号连接设备的数量。这不仅给拥有多台设备（手机、电脑、平板、游戏机、智能家居等）的学习与生活带来了不便，有时也增加了不必要的费用负担。</p><p>本项目旨在：</p><ol><li><strong>原理讲解</strong>：从网络协议底层原理出发，剖析校园网如何识别多设备共享</li><li><strong>提供可行方案</strong>：提供有效的 OpenWrt 及路由器配置</li></ol><h2 id="📚-本指南涵盖的内容" tabindex="-1">📚 本指南涵盖的内容 <a class="header-anchor" href="#📚-本指南涵盖的内容" aria-label="Permalink to “📚 本指南涵盖的内容”">​</a></h2><p>根据技术层级与实施步骤，本指南主要划分为以下四个板块：</p><table tabindex="0"><thead><tr><th style="text-align:left;">模块</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>🔍 传统检测</strong></td><td style="text-align:left;">详细剖析常见的识别手段，包括 <strong>TTL 递减</strong>、<strong>DHCP 指纹</strong>、<strong>HTTP User-Agent (UA) 特征</strong>、<strong>MAC 地址</strong> 等</td></tr><tr><td style="text-align:left;"><strong>🛡️ 深度包检测</strong></td><td style="text-align:left;">针对深度包检测（DPI）识别加密/混淆流量的特点，整理常见的应对思路、防检测策略及潜在风险评估</td></tr><tr><td style="text-align:left;"><strong>🧐 另类检测</strong></td><td style="text-align:left;">针对特殊另类检测，尝试解释其原理和给出解决方案</td></tr><tr><td style="text-align:left;"><strong>⚙️ 详细配置</strong></td><td style="text-align:left;">提供基于 <strong>OpenWrt</strong> 等主流路由器固件的具体操作步骤、关键防火墙规则与参数调整细节</td></tr><tr><td style="text-align:left;"><strong>🛠️ 排查方法</strong></td><td style="text-align:left;">整理自排查流程，帮助快速定位 TTL 防火墙生效情况、UA 泄漏点等疑难杂症</td></tr></tbody></table><h2 id="⚠️-免责声明" tabindex="-1">⚠️ 免责声明 <a class="header-anchor" href="#⚠️-免责声明" aria-label="Permalink to “⚠️ 免责声明”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">注意</p><ol><li>本指南所涉及的技术内容仅供<strong>网络技术学习、学术研究及合法个人使用</strong>参考。</li><li>请自觉遵守您所在学校或网络服务提供商（ISP）的《网络服务使用协议》及相关法律法规。</li><li>作者及贡献者不对因使用本指南中的方法所导致的任何直接或间接后果（包括但不限于封号、断网、设备损坏等）承担责任。</li></ol></div><h2 id="🤝-参与贡献" tabindex="-1">🤝 参与贡献 <a class="header-anchor" href="#🤝-参与贡献" aria-label="Permalink to “🤝 参与贡献”">​</a></h2><p>校园网的检测机制各不相同，且在不断更新。如果你在自己的学校验证了新的方案，或者发现了文档中的错误与补充，非常欢迎参与贡献！</p><ul><li><strong>Star</strong>: 如果觉得本项目不错，欢迎Star⭐</li><li><strong>提交 Issue</strong>：反馈遇到的技术问题、疑难杂症或文档错误。</li><li><strong>提交 PR</strong>：补充新的学校适配案例、完善 OpenWrt 配置脚本或优化文档排版。</li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};